-- Expansao estrutural: sem backfill e sem alteracao de perfis ou identidades Auth.
create schema app_private;
revoke all on schema app_private from public, anon, authenticated;
create table app_private.user_auth_state(
 user_id uuid primary key, username text, must_change_password boolean not null default false,
 password_changed_at timestamptz,password_reset_required_at timestamptz,password_reset_by uuid,
 credential_version bigint not null default 1 check(credential_version>0),state_version bigint not null default 1 check(state_version>0),
 created_at timestamptz not null default statement_timestamp(),updated_at timestamptz not null default statement_timestamp(),
 constraint user_auth_username_check check(username is null or(username=lower(btrim(username)) and username~'^[a-z0-9][a-z0-9._-]{2,39}$')),
 constraint user_auth_password_check check((not must_change_password and password_reset_required_at is null)or(must_change_password and password_reset_required_at is not null))
);
create unique index user_auth_state_username_key on app_private.user_auth_state(username) where username is not null;
create table app_private.identity_operations(
 id uuid primary key default gen_random_uuid(),operation_type text not null check(operation_type in('create_user','create_tenant_admin','change_password','admin_reset_password')),
 empresa_id uuid not null,actor_user_id uuid not null,target_user_id uuid,username text,idempotency_digest text not null,
 status text not null default 'pending' check(status in('pending','completed','failed','compensation_required')),
 state_version bigint not null default 1 check(state_version>0),failure_code text,result jsonb not null default '{}',
 created_at timestamptz not null default statement_timestamp(),updated_at timestamptz not null default statement_timestamp(),expires_at timestamptz not null default(statement_timestamp()+interval '24 hours'),
 unique(operation_type,empresa_id,actor_user_id,idempotency_digest),
 check(username is null or(username=lower(btrim(username)) and username~'^[a-z0-9][a-z0-9._-]{2,39}$')),
 check(jsonb_typeof(result)='object' and octet_length(result::text)<=4096 and not(result ?| array['password','senha','token','access_token','refresh_token','email','technical_email']))
);
create unique index identity_operations_reserved_username_key on app_private.identity_operations(username) where username is not null and status in('pending','compensation_required');
create index identity_operations_expiry_idx on app_private.identity_operations(expires_at);
create table app_private.auth_rate_limits(key_digest text primary key check(key_digest~'^[a-f0-9]{64}$'),window_started_at timestamptz not null,attempt_count integer not null check(attempt_count>=0),blocked_until timestamptz,expires_at timestamptz not null,updated_at timestamptz not null default statement_timestamp());
create index auth_rate_limits_expiry_idx on app_private.auth_rate_limits(expires_at);
create table app_private.identity_audit_outbox(id uuid primary key default gen_random_uuid(),operation_id uuid references app_private.identity_operations(id) on delete restrict,event_type text not null,actor_user_id uuid,target_user_id uuid,empresa_id uuid not null,success boolean not null,failure_code text,correlation_id text not null check(correlation_id~'^[A-Za-z0-9._:-]{1,200}$'),payload jsonb not null default '{}' check(jsonb_typeof(payload)='object' and octet_length(payload::text)<=2048 and not(payload ?| array['password','senha','token','access_token','refresh_token','email','technical_email'])),created_at timestamptz not null default statement_timestamp(),published_at timestamptz);
create index identity_audit_outbox_pending_idx on app_private.identity_audit_outbox(created_at) where published_at is null;
alter schema app_private owner to postgres;
alter table app_private.user_auth_state owner to postgres;
alter table app_private.identity_operations owner to postgres;
alter table app_private.auth_rate_limits owner to postgres;
alter table app_private.identity_audit_outbox owner to postgres;
comment on schema app_private is 'Estado de identidade acessível exclusivamente por funções server-side.';
comment on table app_private.user_auth_state is 'Credenciais públicas nunca são armazenadas aqui; contém somente estado operacional privado.';
comment on column app_private.user_auth_state.user_id is 'Sem FK para Auth: preserva dump/reconciliação e não corrige nem remove órfãos automaticamente.';
comment on column app_private.user_auth_state.password_reset_by is 'UUID histórico do ator, deliberadamente sem ON DELETE SET NULL.';
alter table app_private.user_auth_state enable row level security;
alter table app_private.identity_operations enable row level security;
alter table app_private.auth_rate_limits enable row level security;
alter table app_private.identity_audit_outbox enable row level security;
revoke all on all tables in schema app_private from public,anon,authenticated;grant usage on schema app_private to service_role;
create function public.resolve_login_username(p_username text) returns table(user_id uuid,must_change_password boolean,credential_version bigint) language sql stable security definer set search_path=pg_catalog as $$select s.user_id,s.must_change_password,s.credential_version from app_private.user_auth_state s where s.username=lower(btrim(p_username)) and p_username=lower(btrim(p_username))$$;
create function public.get_private_auth_state(p_user_id uuid) returns table(username text,must_change_password boolean,credential_version bigint,state_version bigint) language sql stable security definer set search_path=pg_catalog as $$select s.username,s.must_change_password,s.credential_version,s.state_version from app_private.user_auth_state s where s.user_id=p_user_id$$;
create function public.consume_auth_rate_limit(p_key_digest text,p_window_seconds integer,p_limit integer,p_now timestamptz default statement_timestamp()) returns table(allowed boolean,retry_after integer) language plpgsql security definer set search_path=pg_catalog as $$declare r app_private.auth_rate_limits%rowtype;b integer;begin if p_key_digest!~'^[a-f0-9]{64}$' or p_window_seconds not between 1 and 86400 or p_limit not between 1 and 1000 then raise exception 'invalid rate limit parameters';end if;delete from app_private.auth_rate_limits where ctid in(select ctid from app_private.auth_rate_limits where expires_at<p_now limit 100);insert into app_private.auth_rate_limits values(p_key_digest,p_now,1,null,p_now+make_interval(secs=>p_window_seconds*8),p_now) on conflict(key_digest)do update set window_started_at=case when app_private.auth_rate_limits.window_started_at+make_interval(secs=>p_window_seconds)<=p_now then p_now else app_private.auth_rate_limits.window_started_at end,attempt_count=case when app_private.auth_rate_limits.window_started_at+make_interval(secs=>p_window_seconds)<=p_now then 1 else app_private.auth_rate_limits.attempt_count+1 end,updated_at=p_now,expires_at=p_now+make_interval(secs=>p_window_seconds*8) returning * into r;if r.blocked_until>p_now then return query select false,ceil(extract(epoch from r.blocked_until-p_now))::integer;return;end if;if r.attempt_count>p_limit then b:=least(p_window_seconds*8,p_window_seconds*(1<<least(3,(r.attempt_count-p_limit-1)/p_limit)));update app_private.auth_rate_limits set blocked_until=p_now+make_interval(secs=>b)where key_digest=p_key_digest;return query select false,b;return;end if;return query select true,0;end$$;
create function public.begin_identity_operation(p_operation_type text,p_empresa_id uuid,p_idempotency_digest text,p_actor_user_id uuid,p_target_user_id uuid,p_username text) returns table(operation_id uuid,operation_status text,operation_result jsonb,operation_created boolean) language plpgsql security definer set search_path=pg_catalog as $$declare n integer;begin if p_operation_type='create_tenant_admin' then if not exists(select 1 from public.super_admins s where s.user_id=p_actor_user_id)then raise exception 'actor not authorized';end if;elsif p_operation_type='change_password' then if p_target_user_id is distinct from p_actor_user_id or not exists(select 1 from public.perfis p join public.empresas e on e.id=p.empresa_id and e.status='ativo' join public.controle_acesso ca on ca.user_id=p.user_id and ca.empresa_id=p.empresa_id and ca.status='ativo' where p.user_id=p_actor_user_id and p.empresa_id=p_empresa_id and p.status='ativo')then raise exception 'actor not authorized';end if;elsif not exists(select 1 from public.perfis p join public.empresas e on e.id=p.empresa_id and e.status='ativo' join public.controle_acesso ca on ca.user_id=p.user_id and ca.empresa_id=p.empresa_id and ca.status='ativo' join public.v_user_roles vr on vr.user_id=p.user_id and vr.empresa_id=p.empresa_id and vr.role_name='system_manager' where p.user_id=p_actor_user_id and p.empresa_id=p_empresa_id and p.status='ativo')then raise exception 'actor not authorized';end if;if p_target_user_id is not null and not exists(select 1 from public.perfis p where p.user_id=p_target_user_id and p.empresa_id=p_empresa_id)then raise exception 'target tenant mismatch';end if;insert into app_private.identity_operations(operation_type,empresa_id,actor_user_id,target_user_id,username,idempotency_digest) values(p_operation_type,p_empresa_id,p_actor_user_id,p_target_user_id,p_username,p_idempotency_digest) on conflict(operation_type,empresa_id,actor_user_id,idempotency_digest)do nothing;get diagnostics n=row_count;return query select o.id,o.status,o.result,n=1 from app_private.identity_operations o where o.operation_type=p_operation_type and o.empresa_id=p_empresa_id and o.actor_user_id=p_actor_user_id and o.idempotency_digest=p_idempotency_digest for update;end$$;
create function public.upsert_private_auth_state(p_operation_id uuid,p_user_id uuid,p_username text,p_must_change_password boolean,p_expected_state_version bigint,p_correlation_id text) returns table(credential_version bigint,state_version bigint) language plpgsql security definer set search_path=pg_catalog as $$declare s app_private.user_auth_state%rowtype;o app_private.identity_operations%rowtype;begin select * into o from app_private.identity_operations where id=p_operation_id and status='pending' for update;if not found then raise exception 'operation conflict';end if;if o.target_user_id is not null and o.target_user_id is distinct from p_user_id then raise exception 'operation target mismatch';end if;if o.operation_type in('create_user','create_tenant_admin') and o.username is distinct from p_username then raise exception 'operation username mismatch';end if;if not exists(select 1 from public.perfis p join public.controle_acesso ca on ca.user_id=p.user_id and ca.empresa_id=p.empresa_id and ca.status='ativo' where p.user_id=p_user_id and p.empresa_id=o.empresa_id and p.status='ativo')then raise exception 'target tenant mismatch';end if;if o.operation_type='create_tenant_admin' and not exists(select 1 from public.v_user_roles vr where vr.user_id=p_user_id and vr.empresa_id=o.empresa_id and vr.role_name='system_manager')then raise exception 'administrator role mismatch';end if;select * into s from app_private.user_auth_state where user_id=p_user_id for update;if found and p_expected_state_version is not null and s.state_version<>p_expected_state_version then raise exception 'state version conflict';end if;insert into app_private.user_auth_state(user_id,username,must_change_password,password_reset_required_at,password_reset_by)values(p_user_id,p_username,p_must_change_password,case when p_must_change_password then statement_timestamp()end,case when p_must_change_password then o.actor_user_id end)on conflict(user_id)do update set username=coalesce(excluded.username,app_private.user_auth_state.username),must_change_password=excluded.must_change_password,password_changed_at=case when excluded.must_change_password then app_private.user_auth_state.password_changed_at else statement_timestamp()end,password_reset_required_at=excluded.password_reset_required_at,password_reset_by=excluded.password_reset_by,credential_version=app_private.user_auth_state.credential_version+1,state_version=app_private.user_auth_state.state_version+1,updated_at=statement_timestamp()returning * into s;update app_private.identity_operations set status='completed',target_user_id=p_user_id,result=case when o.operation_type in('create_user','create_tenant_admin')then jsonb_build_object('user_id',p_user_id,'username',p_username)else'{}'::jsonb end,state_version=state_version+1,updated_at=statement_timestamp()where id=o.id;insert into app_private.identity_audit_outbox(operation_id,event_type,actor_user_id,target_user_id,empresa_id,success,correlation_id)values(o.id,o.operation_type,o.actor_user_id,p_user_id,o.empresa_id,true,p_correlation_id);return query select s.credential_version,s.state_version;end$$;
create function public.finish_identity_operation(p_operation_id uuid,p_status text,p_failure_code text,p_correlation_id text) returns void language plpgsql security definer set search_path=pg_catalog as $$declare o app_private.identity_operations%rowtype;begin if p_status not in('failed','compensation_required')then raise exception 'invalid status';end if;update app_private.identity_operations set status=p_status,failure_code=left(p_failure_code,100),result='{}',state_version=state_version+1,updated_at=statement_timestamp()where id=p_operation_id and status='pending'returning * into o;if not found then raise exception 'operation conflict';end if;insert into app_private.identity_audit_outbox(operation_id,event_type,actor_user_id,target_user_id,empresa_id,success,failure_code,correlation_id)values(o.id,o.operation_type,o.actor_user_id,o.target_user_id,o.empresa_id,false,left(p_failure_code,100),p_correlation_id);end$$;
alter function public.resolve_login_username(text) owner to postgres;alter function public.get_private_auth_state(uuid) owner to postgres;alter function public.consume_auth_rate_limit(text,integer,integer,timestamptz) owner to postgres;alter function public.begin_identity_operation(text,uuid,text,uuid,uuid,text) owner to postgres;alter function public.upsert_private_auth_state(uuid,uuid,text,boolean,bigint,text) owner to postgres;alter function public.finish_identity_operation(uuid,text,text,text) owner to postgres;
revoke all on function public.resolve_login_username(text),public.get_private_auth_state(uuid),public.consume_auth_rate_limit(text,integer,integer,timestamptz),public.begin_identity_operation(text,uuid,text,uuid,uuid,text),public.upsert_private_auth_state(uuid,uuid,text,boolean,bigint,text),public.finish_identity_operation(uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.resolve_login_username(text),public.get_private_auth_state(uuid),public.consume_auth_rate_limit(text,integer,integer,timestamptz),public.begin_identity_operation(text,uuid,text,uuid,uuid,text),public.upsert_private_auth_state(uuid,uuid,text,boolean,bigint,text),public.finish_identity_operation(uuid,text,text,text) to service_role;
